const $=id=>document.getElementById(id);let page=0,admin=false,selected='',source=null;let data={};try{data=JSON.parse(localStorage.getItem('dangha2026')||'{}')}catch{}const names=['당하방송반(DBS)','피구부','영어원서읽기','역사수호대 당크','당당동','건강수호대','또래상담부','와이씨씨유엔','댄스동아리','칸타빌레','공존','아틀리에','클로티카','검도','당하 미들 스타','야구 경기 분석','당하 터볼 태그업','당하 농구','당하여자농구','스왓(SWAT)','신인공지능','당하드론','메아리','누리봄','서로나눔','프리뷰','온이음','플로우(Flow)','당하 남자배구부','당하 여자배구부','날선지성','당찬수학','사띠','여자풋살부'];const sections=['당하의 발자취','배움의 새 공간','스포츠클럽 특집','교실 밖 배움','학생자치 이야기','꿈과 예술','동아리 열전 Ⅰ','동아리 열전 Ⅱ'];const titles=[['함께 걸어온 오늘,\n더 넓은 내일로','배움의 다리를 놓는\n당하 교육공동체','우리가 지켜갈 학교의 상징','당하의 발자취, 우리가 쓰는 기록'],['새로운 생각이 자라는 곳,\nAI 융합실과 도서관','함께 달리고 함께 웃는\n당하 체육한마당','질문에서 시작되는 배움','책과 기술이 만나는 시간'],['여덟 종목, 하나의 마음\n당하의 도전은 계속된다','승패를 넘어 배우는\n팀워크의 힘','우리 팀을 응원하는 방법','훈련의 순간도 빛나는 기록'],['교실 밖에서 만나는\n더 넓은 세상','SSG 스쿨데이,\n함께 즐기는 야구의 매력','월드컵 캠페인으로 만나는 세계','1·2·3학년 현장체험학습'],['우리의 목소리로 만드는\n더 좋은 학교','리더십 캠프,\n함께 결정하는 연습','교복데이와 클린데이','등굣길 응원과 양성평등'],['나의 가능성을 발견하는\n진로 탐색의 시간','칸타빌레, 서로의 소리로\n완성하는 하모니','직업 체험에서 찾는 질문','말벌 소동, 안전을 돌아보다']];const body='이 기사는 제공된 기획을 바탕으로 작성한 편집용 초안입니다. 실제 행사 일정과 참여 대상은 학교의 확인이 필요합니다. 당하의 배움은 함께 질문하는 순간에서 시작됩니다. 서로의 생각을 듣는 과정은 새로운 시선을 열어 줍니다. 교실에서 배운 내용을 생활과 연결하는 경험도 소중합니다. 작은 역할을 맡아 끝까지 해내는 태도는 성장의 밑거름이 됩니다. 친구와 협력하며 어려움을 해결하는 방법을 배울 수 있습니다. 결과만큼 준비 과정의 노력도 기록할 가치가 있습니다. 각자의 속도를 존중하는 마음은 공동체를 더욱 단단하게 만듭니다. 참여한 학생들의 실제 소감이 더해지면 이야기는 더욱 생생해질 것입니다. 담당 선생님의 안내와 현장 사진도 함께 확인해 주세요. 기사에 들어갈 이름과 인용문은 당사자의 확인을 거쳐야 합니다. 정확한 사실을 담아 우리 학교의 시간을 오래 기억하고자 합니다. 오늘의 경험이 다음 도전으로 이어지기를 기대합니다.';function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function editable(key,val,tag='p',cls=''){return `<${tag} class="${cls}" data-key="${key}" ${admin?'contenteditable="true"':''}>${esc(data[key]??val)}</${tag}>`}function art(key,title,short=false){return `<article class="article"><span class="tag">${short?'OUR SCHOOL':'SPECIAL REPORT · 2026'}</span>${editable(key+'t',title,'h2')}${editable(key+'b',short?body.split('. ').slice(0,5).join('. ')+'.':body)}</article>`}function illustration(){return `<svg class="landscape" viewBox="0 0 700 360" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg"><rect width="700" height="360" fill="#e0e8d7"/><circle cx="565" cy="70" r="35" fill="#f6f3cd"/><path d="M0 185L130 100 275 186 395 120 570 190 700 120V360H0" fill="#bbcda8"/><path d="M0 245Q170 180 340 242T700 230V360H0" fill="#809b72"/><path d="M320 360L410 242 455 242 465 360" fill="#d4cfab"/><rect x="105" y="148" width="380" height="119" fill="#f4f0da"/><rect x="135" y="127" width="330" height="28" fill="#49634c"/><rect x="270" y="100" width="70" height="167" fill="#e7e4cb"/><path d="M260 100L305 76 350 100" fill="#49634c"/><g fill="#6e8e81">${Array.from({length:12},(_,i)=>`<rect x="${125+(i%6)*59}" y="${169+Math.floor(i/6)*46}" width="33" height="28"/>`).join('')}</g><rect x="290" y="228" width="32" height="39" fill="#3c5a49"/><g fill="#42664d"><circle cx="65" cy="215" r="40"/><circle cx="535" cy="216" r="35"/><circle cx="620" cy="208" r="49"/></g><text x="350" y="334" text-anchor="middle" fill="#f5f4df" font-size="12" letter-spacing="5">DANGHA · OUR GROWING DAYS</text></svg>`}function photo(key){let p=data[key];return `<div class="photo" style="${p?`width:${p.width}%;aspect-ratio:${p.ratio};height:auto;border-radius:${p.radius};`:''}">${p?`<img src="${p.url}" alt="편집자가 등록한 소식지 사진">`:illustration()}${admin?`<button data-photo="${key}">＋ 사진 편집</button>`:''}</div>`}function render(){ $('nav').innerHTML=sections.map((s,i)=>`<button class="${i===page?'active':''}" data-page="${i}">${i+1}면 <span>${s}</span></button>`).join('');$('section').textContent=`THE NEWSPAPER / ${String(page+1).padStart(2,'0')} — ${sections[page]}`;$('count').textContent=`${page+1} / 8`;$('prev').disabled=page===0;$('next').disabled=page===7;$('nextBottom').textContent=page===7?'1면으로 돌아가기 ↗':'다음 면 읽기 →';let head=`<div class="mastline"><span>함께 성장하는 우리들의 이야기</span><span>2026 · 특별호 · 편집용 초안</span></div><div class="masthead">당하브릿지</div><div class="mastsub">D A N G H A　 B R I D G E</div><div class="dateline"><span>당하중학교 소식지</span><span>${sections[page]}</span><span>제 ${page+1} 면</span></div>`;if(page<6){let t=titles[page];head+=`<div class="storygrid"><section>${art('p'+page+'a',t[0]) .replace('<p class=""', '<p class="lead"')}${photo('p'+page+'photo')}<div class="caption">당하의 배움과 성장을 담은 학교 일러스트 · 실제 사진으로 교체할 수 있습니다.</div></section><aside class="aside">${art('p'+page+'b',t[1],true)}<div class="quote"><span class="tag">EDITOR’S NOTE</span><h3>“함께하는 오늘이<br>우리의 내일이 됩니다.”</h3><p>이 지면은 학교 소식을 담기 위한 초안입니다. 실제 인사말, 학교 연혁, 교훈·교화·교목은 확인한 자료로 수정해 주세요.</p></div></aside></div><div class="lower">${art('p'+page+'c',t[2],true)}${art('p'+page+'d',t[3],true)}</div>`}else{head+=`<h2 class="sectiontitle">서로 다른 관심, 함께 빛나는 우리</h2><p class="lead">CLUB STORIES · ${page===6?'01—16':'17—34'}　 /　 동아리 소개는 실제 활동 내용으로 수정해 주세요.</p><div class="clubs">${names.slice(page===6?0:16,page===6?16:34).map((n,i)=>{let num=i+(page===6?0:16);return `<article class="club"><span class="num">${String(num+1).padStart(2,'0')}</span>${editable('c'+num+'t',n,'h2')}${editable('c'+num+'b','관심을 나누고 함께 도전하는 '+n+'입니다. 활동 목표, 정기 모임, 한 해의 성과와 학생 소감을 이곳에 담아 주세요. 동아리의 개성이 드러나는 실제 소개글을 기다립니다.')}${admin||data['c'+num+'photo']?photo('c'+num+'photo'):''}</article>`}).join('')}</div>`}head+=`<div class="folio"><span>DANGHA BRIDGE · 2026</span><span>${String(page+1).padStart(2,'0')}</span></div>`;$('paper').innerHTML=head;$('savebar').hidden=!admin;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(+b.dataset.page));document.querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{data[el.dataset.key]=el.innerText});document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>openCrop(b.dataset.photo))}function go(n){page=n;render();$('nav').scrollIntoView({behavior:'smooth',block:'start'})}function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000)}$('prev').onclick=()=>go(Math.max(0,page-1));$('next').onclick=()=>go(Math.min(7,page+1));$('nextBottom').onclick=()=>go((page+1)%8);$('admin').onclick=()=>{$('login').showModal();$('pw').focus()};$('unlock').onclick=()=>{if($('pw').value==='1234'){admin=true;$('login').close();$('pw').value='';$('error').textContent='';render()}else $('error').textContent='비밀번호를 확인해 주세요.'};$('pw').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('unlock').click()}};$('exit').onclick=()=>{admin=false;render()};$('save').onclick=()=>{try{localStorage.setItem('dangha2026',JSON.stringify(data));toast('이 브라우저에 저장했습니다.')}catch{toast('저장 공간이 부족합니다. 백업을 내보내 주세요.')}};$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='당하브릿지-2026-백업.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import').onchange=async e=>{try{let v=JSON.parse(await e.target.files[0].text());if(!v||Array.isArray(v)||typeof v!=='object')throw Error();for(let [k,x]of Object.entries(v)){if(!/^(p\d+(?:[abcd][tb]|e[a-z0-9]+[tb]|photo|(?:[abcd]|e[a-z0-9]+)photo[1-3]|greet(?:[tbs]|photo))|c\d+(?:[tb]|photo))$/.test(k))throw Error();if(k.endsWith('photo')){if(typeof x!=='object'||!/^data:image\/(png|jpeg|webp);base64,/.test(x.url)||!Number.isFinite(x.ratio)||x.ratio<=0||!Number.isFinite(x.width)||x.width<20||x.width>100||!['0','18px','50%'].includes(x.radius))throw Error()}else if(typeof x!=='string')throw Error()}data=v;render();toast('백업을 불러왔습니다. 저장 버튼으로 보관하세요.')}catch{toast('유효한 소식지 백업 파일을 선택해 주세요.')}e.target.value=''};$('print').onclick=()=>window.print();
function openCrop(key){selected=key;source=null;$('upload').value='';$('zoom').value=1;$('x').value=50;$('y').value=50;$('width').value=data[key]?.width||100;$('height').value=300;$('shape').value='rect';$('crop').showModal();if(data[key]){let im=new Image();im.onload=()=>{source=im;draw()};im.src=data[key].url}else draw()}function dims(){let shape=$('shape').value;let w=600*+$('width').value/100,h=+$('height').value;if(shape==='circle')h=w;if(shape.startsWith('portrait'))h=w*4/3;return {w,h,shape}}function draw(){let {w,h,shape}=dims();let c=$('canvas');c.width=Math.round(w*1.6);c.height=Math.round(h*1.6);let ctx=c.getContext('2d');ctx.fillStyle='#dce3d1';ctx.fillRect(0,0,c.width,c.height);if(source){let scale=Math.max(c.width/source.width,c.height/source.height)*+$('zoom').value;let iw=source.width*scale,ih=source.height*scale;ctx.drawImage(source,-(iw-c.width)*+$('x').value/100,-(ih-c.height)*+$('y').value/100,iw,ih)}else{ctx.fillStyle='#718166';ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText('사진을 선택해 주세요',c.width/2,c.height/2)}c.style.borderRadius=shape==='circle'?'50%':/round/i.test(shape)?'18px':'0';$('wo').value=$('width').value+'%';$('ho').value=Math.round(h)+'px';$('height').disabled=shape==='circle'||shape.startsWith('portrait')}['width','height','shape','zoom','x','y'].forEach(id=>$(id).oninput=draw);$('upload').onchange=e=>{let file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('이미지 파일을 선택해 주세요.');return}let url=URL.createObjectURL(file),im=new Image();im.onload=()=>{source=im;draw();URL.revokeObjectURL(url)};im.onerror=()=>{toast('이 이미지를 열 수 없습니다. JPG 또는 PNG로 다시 선택해 주세요.');URL.revokeObjectURL(url)};im.src=url};$('apply').onclick=()=>{if(!source){toast('사진을 먼저 선택해 주세요.');return}let {w,h,shape}=dims();data[selected]={url:$('canvas').toDataURL('image/jpeg',.85),width:+$('width').value,ratio:w/h,radius:shape==='circle'?'50%':/round/i.test(shape)?'18px':'0'};$('crop').close();render()};$('delete').onclick=()=>{delete data[selected];$('crop').close();render()};$('closecrop').onclick=()=>$('crop').close();render();
